  function expireTrials(){let changed=false;for(const trial of state.tryouts){if(trial.status==='provisional'&&now()>=trial.deadline){trial.status='expired';trial.roleGranted=false;trial.expiredAt=now();log('DM',`Seu prazo de 48 horas terminou sem cadastro. Seu cargo foi removido e o tryout foi reprovado. Você poderá iniciar um novo tryout.`,trial.participant);log('CANAL',`Prazo encerrado para ${trial.participant}. Cargo provisório removido; acesso aos canais revogado.`,trial.participant);activity(`${trial.participant} perdeu o acesso por cadastro pendente.`, 'clock');changed=true;}}if(changed)save();return changed;}
